1	import { useState } from "react";
2	import { toast } from "sonner";
3	import { format } from "date-fns";
4	import {
5	  Users,
6	  Crown,
7	  Shield,
8	  UserPlus,
9	  Trash2,
10	  Loader2,
11	  Mail,
12	  RotateCw,
13	  Briefcase,
14	  FileText,
15	  CheckSquare,
16	  ArrowRight,
17	} from "lucide-react";
18	import { Link } from "react-router-dom";
19	import SidebarLayout from "@/components/SidebarLayout";
20	import { FadeIn } from "@/components/ui/fade-in";
21	import { StaggerList } from "@/components/ui/stagger-list";
22	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
23	import { Button } from "@/components/ui/button";
24	import { Input } from "@/components/ui/input";
25	import { Badge } from "@/components/ui/badge";
26	import { Skeleton } from "@/components/ui/skeleton";
27	import {
28	  Select,
29	  SelectContent,
30	  SelectItem,
31	  SelectTrigger,
32	  SelectValue,
33	} from "@/components/ui/select";
34	import {
35	  Table,
36	  TableBody,
37	  TableCell,
38	  TableHead,
39	  TableHeader,
40	  TableRow,
41	} from "@/components/ui/table";
42	import {
43	  AlertDialog,
44	  AlertDialogAction,
45	  AlertDialogCancel,
46	  AlertDialogContent,
47	  AlertDialogDescription,
48	  AlertDialogFooter,
49	  AlertDialogHeader,
50	  AlertDialogTitle,
51	  AlertDialogTrigger,
52	} from "@/components/ui/alert-dialog";
53	import { useTeam, type TeamMember, type TeamInvitation } from "@/hooks/useTeam";
54	import { useTeamDashboard } from "@/hooks/useTeamDashboard";
55	import ActivityItem from "@/components/ActivityItem";
56	import { supabase } from "@/integrations/supabase/client";
57	import { useAuth } from "@/hooks/useAuth";
58	
59	type TeamRole = "owner" | "admin" | "member";
60	
61	const ROLE_LABELS: Record<TeamRole, string> = {
62	  owner: "Owner",
63	  admin: "Admin",
64	  member: "Member",
65	};
66	
67	const ROLE_VARIANTS: Record<TeamRole, "default" | "secondary" | "outline"> = {
68	  owner: "default",
69	  admin: "secondary",
70	  member: "outline",
71	};
72	
73	function RoleBadge({ role }: { role: TeamRole }) {
74	  const Icon = role === "owner" ? Crown : role === "admin" ? Shield : Users;
75	  return (
76	    <Badge variant={ROLE_VARIANTS[role]} className="gap-1 text-xs font-medium">
77	      <Icon className="h-3 w-3" />
78	      {ROLE_LABELS[role]}
79	    </Badge>
80	  );
81	}
82	
83	function MembersSkeleton() {
84	  return (
85	    <div className="space-y-3">
86	      {[1, 2, 3].map((i) => (
87	        <div key={i} className="flex items-center gap-4 px-4 py-3">
88	          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
89	          <div className="flex-1 space-y-1.5">
90	            <Skeleton className="h-4 w-48" />
91	            <Skeleton className="h-3 w-32" />
92	          </div>
93	          <Skeleton className="h-6 w-16 rounded-full" />
94	          <Skeleton className="h-8 w-8 rounded" />
95	        </div>
96	      ))}
97	    </div>
98	  );
99	}
100	
101	const Team = () => {
102	  const { user } = useAuth();
103	  const { team, members, invitations, myRole, isLoading, refetch } = useTeam();
104	
105	  const [inviteEmail, setInviteEmail] = useState("");
106	  const [inviteRole, setInviteRole] = useState<"admin" | "member">("member");
107	  const [isSendingInvite, setIsSendingInvite] = useState(false);
108	  const [revokingId, setRevokingId] = useState<string | null>(null);
109	  const [removingId, setRemovingId] = useState<string | null>(null);
110	  const [updatingRoleId, setUpdatingRoleId] = useState<string | null>(null);
111	
112	  const canManage = myRole === "owner" || myRole === "admin";
113	
114	  async function handleInvite(e: React.FormEvent) {
115	    e.preventDefault();
116	    if (!inviteEmail.trim() || !team?.id) return;
117	
118	    setIsSendingInvite(true);
119	    try {
120	      const { data: { session } } = await supabase.auth.getSession();
121	      if (!session?.access_token) throw new Error("Not authenticated");
122	
123	      const res = await fetch(
124	        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-team-invite`,
125	        {
126	          method: "POST",
127	          headers: {
128	            "Content-Type": "application/json",
129	            "Authorization": `Bearer ${session.access_token}`,
130	            "apikey": import.meta.env.VITE_SUPABASE_ANON_KEY,
131	          },
132	          body: JSON.stringify({
133	            team_id: team.id,
134	            email: inviteEmail.trim().toLowerCase(),
135	            role: inviteRole,
136	          }),
137	        }
138	      );
139	
140	      const json = await res.json();
141	      if (!res.ok) throw new Error(json.error || "Failed to send invitation");
142	
143	      toast.success(`Invitation sent to ${inviteEmail.trim()}`);
144	      setInviteEmail("");
145	      refetch();
146	    } catch (err: unknown) {
147	      const msg = err instanceof Error ? err.message : "Failed to send invitation";
148	      toast.error(msg);
149	    } finally {
150	      setIsSendingInvite(false);
151	    }
152	  }
153	
154	  async function handleRevokeInvite(id: string, email: string) {
155	    setRevokingId(id);
156	    try {
157	      const { error } = await (supabase as any)
158	        .from("team_invitations")
159	        .update({ status: "revoked" })
160	        .eq("id", id);
161	
162	      if (error) throw error;
163	
164	      toast.success(`Invitation to ${email} revoked`);
165	      refetch();
166	    } catch (err: unknown) {
167	      toast.error("Failed to revoke invitation");
168	    } finally {
169	      setRevokingId(null);
170	    }
171	  }
172	
173	  async function handleChangeRole(member: TeamMember, newRole: TeamRole) {
174	    if (newRole === member.role) return;
175	    setUpdatingRoleId(member.id);
176	    try {
177	      const { error } = await (supabase as any)
178	        .from("team_members")
179	        .update({ role: newRole })
180	        .eq("id", member.id);
181	
182	      if (error) throw error;
183	
184	      toast.success(`Role updated to ${ROLE_LABELS[newRole]}`);
185	      refetch();
186	    } catch (err: unknown) {
187	      toast.error("Failed to update role");
188	    } finally {
189	      setUpdatingRoleId(null);
190	    }
191	  }
192	
193	  async function handleRemoveMember(member: TeamMember) {
194	    setRemovingId(member.id);
195	    try {
196	      const { error } = await (supabase as any)
197	        .from("team_members")
198	        .delete()
199	        .eq("id", member.id);
200	
201	      if (error) throw error;
202	
203	      toast.success("Member removed from team");
204	      refetch();
205	    } catch (err: unknown) {
206	      toast.error("Failed to remove member");
207	    } finally {
208	      setRemovingId(null);
209	    }
210	  }
211	
212	  const pendingInvitations = invitations.filter((inv) => inv.status === "pending");
213	  const nonOwnerMembers = members.filter((m) => m.role !== "owner");
214	
215	  const { data: dashboard, isLoading: dashLoading } = useTeamDashboard(team?.id ?? null);
216	
217	  // Stat cards config
218	  const statCards = [
219	    {
220	      icon: Briefcase,
221	      label: "Total Jobs",
222	      value: dashboard?.totalJobs ?? 0,
223	    },
224	    {
225	      icon: FileText,
226	      label: "Active Candidates",
227	      value: dashboard?.activeCandidates ?? 0,
228	    },
229	    {
230	      icon: CheckSquare,
231	      label: "Pending Tasks",
232	      value: dashboard?.pendingTasks ?? 0,
233	    },
234	    {
235	      icon: Users,
236	      label: "Team Members",
237	      value: dashboard?.memberCount ?? 0,
238	    },
239	  ];
240	
241	  return (
242	    <SidebarLayout>
243	      <main className="w-full max-w-2xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
244	        <FadeIn>
245	          <div className="flex items-center justify-between mb-1">
246	            <h1 className="text-2xl font-bold text-foreground">Team</h1>
247	            {team && (
248	              <span className="text-sm text-muted-foreground">{team.name}</span>
249	            )}
250	          </div>
251	          <p className="text-sm text-muted-foreground mb-6">
252	            Manage your team members and pending invitations.
253	          </p>
254	        </FadeIn>
255	
256	        {/* ── Dashboard section (only when team exists) ── */}
257	        {team && (
258	          <div className="space-y-4 mb-6">
259	            {/* Stats row */}
260	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
261	              {statCards.map(({ icon: Icon, label, value }) => (
262	                <Card key={label} className="border border-border/60 shadow-sm">
263	                  <CardContent className="p-4">
264	                    <div className="flex items-center gap-2.5 mb-2">
265	                      <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
266	                        <Icon className="h-4 w-4 text-primary" />
267	                      </div>
268	                    </div>
269	                    {dashLoading ? (
270	                      <Skeleton className="h-7 w-12 mb-1" />
271	                    ) : (
272	                      <p className="text-2xl font-bold text-foreground">{value}</p>
273	                    )}
274	                    <p className="text-xs text-muted-foreground">{label}</p>
275	                  </CardContent>
276	                </Card>
277	              ))}
278	            </div>
279	
280	            {/* Recent Activity card */}
281	            <Card className="border border-border/60 shadow-sm">
282	              <CardHeader className="pb-2 pt-4">
283	                <div className="flex items-center justify-between">
284	                  <CardTitle className="text-sm font-semibold">Recent Activity</CardTitle>
285	                  <Link
286	                    to="/activity"
287	                    className="inline-flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors font-medium"
288	                  >
289	                    View all
290	                    <ArrowRight className="h-3 w-3" />
291	                  </Link>
292	                </div>
293	              </CardHeader>
294	              <CardContent className="pb-3">
295	                {dashLoading ? (
296	                  <div className="space-y-2">
297	                    {[1, 2, 3].map((i) => (
298	                      <Skeleton key={i} className="h-9 w-full rounded-lg" />
299	                    ))}
300	                  </div>
301	                ) : !dashboard?.recentActivity.length ? (
302	                  <p className="text-sm text-muted-foreground py-2">No activity yet</p>
303	                ) : (
304	                  <div className="divide-y divide-border/40">
305	                    {dashboard.recentActivity.map((activity) => (
306	                      <ActivityItem key={activity.id} activity={activity} compact />
307	                    ))}
308	                  </div>
309	                )}
310	              </CardContent>
311	            </Card>
312	
313	            {/* Task summary by assignee */}
314	            {!dashLoading && dashboard?.tasksByAssignee && dashboard.tasksByAssignee.length > 0 && (
315	              <Card className="border border-border/60 shadow-sm">
316	                <CardHeader className="pb-2 pt-4">
317	                  <CardTitle className="text-sm font-semibold">Task Summary by Member</CardTitle>
318	                </CardHeader>
319	                <CardContent className="p-0">
320	                  <Table>
321	                    <TableHeader>
322	                      <TableRow>
323	                        <TableHead className="text-xs">Member</TableHead>
324	                        <TableHead className="text-xs text-right">Pending</TableHead>
325	                        <TableHead className="text-xs text-right">Completed</TableHead>
326	                      </TableRow>
327	                    </TableHeader>
328	                    <TableBody>
329	                      {dashboard.tasksByAssignee.map((row) => {
330	                        const member = members.find((m) => m.user_id === row.user_id);
331	                        const label = member?.email ?? row.user_id.slice(0, 8) + "…";
332	                        return (
333	                          <TableRow key={row.user_id}>
334	                            <TableCell className="text-sm font-medium">{label}</TableCell>
335	                            <TableCell className="text-sm text-right text-amber-600 dark:text-amber-400 font-medium">
336	                              {row.pending}
337	                            </TableCell>
338	                            <TableCell className="text-sm text-right text-emerald-600 dark:text-emerald-400 font-medium">
339	                              {row.completed}
340	                            </TableCell>
341	                          </TableRow>
342	                        );
343	                      })}
344	                    </TableBody>
345	                  </Table>
346	                </CardContent>
347	              </Card>
348	            )}
349	          </div>
350	        )}
351	
352	        <StaggerList className="space-y-6" stagger={0.08}>
353	          {/* Invite card — only visible to owners/admins */}
354	          {canManage && (
355	            <Card className="border border-border/60 shadow-sm">
356	              <CardHeader className="pb-3">
357	                <CardTitle className="text-sm font-semibold flex items-center gap-2">
358	                  <UserPlus className="h-4 w-4 text-primary" />
359	                  Invite a teammate
360	                </CardTitle>
361	              </CardHeader>
362	              <CardContent>
363	                <form onSubmit={handleInvite} className="flex flex-col sm:flex-row gap-2">
364	                  <div className="relative flex-1">
365	                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
366	                    <Input
367	                      type="email"
368	                      placeholder="colleague@company.com"
369	                      value={inviteEmail}
370	                      onChange={(e) => setInviteEmail(e.target.value)}
371	                      className="pl-9"
372	                      required
373	                      disabled={isSendingInvite}
374	                    />
375	                  </div>
376	                  <Select
377	                    value={inviteRole}
378	                    onValueChange={(v) => setInviteRole(v as "admin" | "member")}
379	                    disabled={isSendingInvite}
380	                  >
381	                    <SelectTrigger className="w-full sm:w-32">
382	                      <SelectValue />
383	                    </SelectTrigger>
384	                    <SelectContent>
385	                      <SelectItem value="member">Member</SelectItem>
386	                      <SelectItem value="admin">Admin</SelectItem>
387	                    </SelectContent>
388	                  </Select>
389	                  <Button
390	                    type="submit"
391	                    disabled={isSendingInvite || !inviteEmail.trim()}
392	                    className="gap-1.5 shrink-0"
393	                  >
394	                    {isSendingInvite ? (
395	                      <Loader2 className="h-4 w-4 animate-spin" />
396	                    ) : (
397	                      <UserPlus className="h-4 w-4" />
398	                    )}
399	                    Send invite
400	                  </Button>
401	                </form>
402	              </CardContent>
403	            </Card>
404	          )}
405	
406	          {/* Pending invitations */}
407	          {(pendingInvitations.length > 0 || (isLoading && canManage)) && (
408	            <Card className="border border-border/60 shadow-sm">
409	              <CardHeader className="pb-3">
410	                <div className="flex items-center justify-between">
411	                  <CardTitle className="text-sm font-semibold flex items-center gap-2">
412	                    <Mail className="h-4 w-4 text-primary" />
413	                    Pending invitations
414	                    {!isLoading && (
415	                      <Badge variant="secondary" className="ml-1 text-xs">
416	                        {pendingInvitations.length}
417	                      </Badge>
418	                    )}
419	                  </CardTitle>
420	                  <Button
421	                    variant="ghost"
422	                    size="icon"
423	                    className="h-7 w-7"
424	                    onClick={() => refetch()}
425	                    disabled={isLoading}
426	                    aria-label="Refresh invitations"
427	                  >
428	                    <RotateCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
429	                  </Button>
430	                </div>
431	              </CardHeader>
432	              <CardContent className="p-0">
433	                {isLoading ? (
434	                  <div className="space-y-2 p-4">
435	                    {[1, 2].map((i) => (
436	                      <Skeleton key={i} className="h-10 w-full rounded-md" />
437	                    ))}
438	                  </div>
439	                ) : (
440	                  <Table>
441	                    <TableHeader>
442	                      <TableRow>
443	                        <TableHead className="text-xs">Email</TableHead>
444	                        <TableHead className="text-xs">Role</TableHead>
445	                        <TableHead className="text-xs">Expires</TableHead>
446	                        {canManage && <TableHead className="text-xs w-16" />}
447	                      </TableRow>
448	                    </TableHeader>
449	                    <TableBody>
450	                      {pendingInvitations.map((inv: TeamInvitation) => (
451	                        <TableRow key={inv.id}>
452	                          <TableCell className="text-sm font-medium">{inv.email}</TableCell>
453	                          <TableCell>
454	                            <RoleBadge role={inv.role} />
455	                          </TableCell>
456	                          <TableCell className="text-xs text-muted-foreground">
457	                            {format(new Date(inv.expires_at), "MMM d, yyyy")}
458	                          </TableCell>
459	                          {canManage && (
460	                            <TableCell>
461	                              <Button
462	                                variant="ghost"
463	                                size="icon"
464	                                className="h-7 w-7 text-muted-foreground hover:text-destructive"
465	                                onClick={() => handleRevokeInvite(inv.id, inv.email)}
466	                                disabled={revokingId === inv.id}
467	                                aria-label={`Revoke invite for ${inv.email}`}
468	                              >
469	                                {revokingId === inv.id ? (
470	                                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
471	                                ) : (
472	                                  <Trash2 className="h-3.5 w-3.5" />
473	                                )}
474	                              </Button>
475	                            </TableCell>
476	                          )}
477	                        </TableRow>
478	                      ))}
479	                    </TableBody>
480	                  </Table>
481	                )}
482	              </CardContent>
483	            </Card>
484	          )}
485	
486	          {/* Members table */}
487	          <Card className="border border-border/60 shadow-sm">
488	            <CardHeader className="pb-3">
489	              <div className="flex items-center justify-between">
490	                <CardTitle className="text-sm font-semibold flex items-center gap-2">
491	                  <Users className="h-4 w-4 text-primary" />
492	                  Members
493	                  {!isLoading && (
494	                    <Badge variant="secondary" className="ml-1 text-xs">
495	                      {members.length}
496	                    </Badge>
497	                  )}
498	                </CardTitle>
499	                <Button
500	                  variant="ghost"
501	                  size="icon"
502	                  className="h-7 w-7"
503	                  onClick={() => refetch()}
504	                  disabled={isLoading}
505	                  aria-label="Refresh members"
506	                >
507	                  <RotateCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
508	                </Button>
509	              </div>
510	            </CardHeader>
511	            <CardContent className="p-0">
512	              {isLoading ? (
513	                <MembersSkeleton />
514	              ) : members.length === 0 ? (
515	                <div className="flex flex-col items-center justify-center py-12 space-y-3 text-center px-4">
516	                  <div className="rounded-xl bg-muted/50 p-4">
517	                    <Users className="h-7 w-7 text-muted-foreground/50" />
518	                  </div>
519	                  <div className="space-y-1">
520	                    <p className="text-sm font-medium text-foreground">No team yet</p>
521	                    <p className="text-sm text-muted-foreground max-w-xs">
522	                      Invite a colleague above to start collaborating on job rankings.
523	                    </p>
524	                  </div>
525	                </div>
526	              ) : (
527	                <Table>
528	                  <TableHeader>
529	                    <TableRow>
530	                      <TableHead className="text-xs">Member</TableHead>
531	                      <TableHead className="text-xs">Role</TableHead>
532	                      <TableHead className="text-xs">Joined</TableHead>
533	                      {canManage && <TableHead className="text-xs w-12" />}
534	                    </TableRow>
